/* eslint-disable no-console */
import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import {
  Lock, Mail, Eye, EyeOff, LogIn, AlertCircle,
  Activity, Shield, ArrowRight, User, Key, Zap, MapPin, Sparkles
} from 'lucide-react';


const ADMIN_HINT = { username: 'admin', password: 'admin123' };
const USER_HINT = { password: 'user123' };


const LoginPage = () => {
  const { login } = useAuth();

  // Form state
  const [formData, setFormData] = useState({ identifier: '', password: '' });
  const [showPassword, setShowPassword] = useState(false);
  const [capsLock, setCapsLock] = useState(false);

  // UX state
  const [error, setError] = useState('');
  const [fieldErrors, setFieldErrors] = useState({ identifier: '', password: '' });
  const [isLoading, setIsLoading] = useState(false);
  const [touched, setTouched] = useState({ identifier: false, password: false });

  // Refs
  const idInputRef = useRef(null);
  const pwdInputRef = useRef(null);
  const submitRef = useRef(null);

  // Admin check
  const isAdminLogin = (id) => {
    const v = String(id || '').trim().toLowerCase();
    return v === 'admin' || v === 'admin@toll.com';
  };

  // Simple validators
  const validate = useCallbackFormValidator();
  const validation = useMemo(() => validate(formData), [formData, validate]);

  const canSubmit = useMemo(() => {
    return !validation.identifier && !validation.password && !isLoading && formData.identifier.trim() && formData.password.trim();
  }, [validation, isLoading, formData]);

  // Autofocus identifier on mount
  useEffect(() => {
    idInputRef.current?.focus();
  }, []);

  // CapsLock detection
  const handleKeyDetection = (e) => {
    const caps = e.getModifierState && e.getModifierState('CapsLock');
    setCapsLock(Boolean(caps));
  };

  // Input change
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((p) => ({ ...p, [name]: value }));
    setError('');
    setFieldErrors((p) => ({ ...p, [name]: '' }));
  };

  // On blur (field level)
  const handleBlur = (e) => {
    const { name } = e.target;
    setTouched((p) => ({ ...p, [name]: true }));
    const v = validate(formData);
    setFieldErrors((p) => ({ ...p, [name]: v[name] || '' }));
  };

  // Fill demo credentials quickly
  const fillAdmin = () => {
    setFormData({ identifier: ADMIN_HINT.username, password: ADMIN_HINT.password });
    setTouched({ identifier: true, password: true });
    setFieldErrors({ identifier: '', password: '' });
    pwdInputRef.current?.focus();
  };

  const fillUser = () => {
    setFormData((p) => ({ identifier: p.identifier || '1234567891', password: USER_HINT.password }));
    setTouched({ identifier: true, password: true });
    setFieldErrors({ identifier: '', password: '' });
    pwdInputRef.current?.focus();
  };

  // Mock login function for production/demo
  const mockLogin = (data) => {
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve({
          data: {
            admin: { username: data.identifier.toLowerCase() === 'admin' ? 'admin' : undefined },
            user: data.identifier.toLowerCase() !== 'admin' ? {
              owner_name: 'Demo User',
              email: data.identifier,
              plate: 'DEMO123',
              rfid_uid: 'DEMO_UID'
            } : undefined,
            token: 'FAKE_TOKEN_123456',
            message: ''
          },
        });
      }, 500);
    });
  };

  // Submit (with mock for production)
  const handleSubmit = async (e) => {
    e.preventDefault();
    setTouched({ identifier: true, password: true });

    const v = validate(formData);
    if (v.identifier || v.password) {
      setFieldErrors(v);
      const focusTarget = v.identifier ? idInputRef : v.password ? pwdInputRef : null;
      focusTarget?.current?.focus();
      return;
    }

    setIsLoading(true);
    setError('');

    try {
      const identifier = formData.identifier.trim();

      if (process.env.NODE_ENV === 'production') {
        // Use mock login in production (GitHub Pages)
        const res = await mockLogin(formData);
        const data = res.data;

        if (isAdminLogin(identifier.toLowerCase())) {
          const userData = { name: data.admin?.username || 'Admin', email: 'admin@toll.com', role: 'admin' };
          login(userData, 'admin', data.token);
        } else {
          const userData = {
            name: data.user?.owner_name || 'User',
            email: data.user?.email || '',
            plate: data.user?.plate,
            rfid_uid: data.user?.rfid_uid,
            role: 'user',
          };
          localStorage.setItem('userData', JSON.stringify(userData));
          login(userData, 'user', data.token);
        }
      } else {
        // Real backend call for development
        let res;
        if (isAdminLogin(identifier.toLowerCase())) {
          res = await fetch('http://localhost:5000/api/admin/login', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ username: 'admin', password: formData.password }),
          });
        } else {
          res = await fetch('http://localhost:5000/api/user/login', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ identifier, password: formData.password }),
          });
        }

        const data = await safeJson(res);

        if (res.ok) {
          if (isAdminLogin(identifier.toLowerCase())) {
            const userData = { name: data.admin?.username || 'Admin', email: 'admin@toll.com', role: 'admin' };
            login(userData, 'admin', data.token);
          } else {
            const userData = {
              name: data.user?.owner_name || 'User',
              email: data.user?.email || '',
              plate: data.user?.plate,
              rfid_uid: data.user?.rfid_uid,
              role: 'user',
            };
            localStorage.setItem('userData', JSON.stringify(userData));
            login(userData, 'user', data.token);
          }
        } else {
          if (res.status === 401) {
            setError('Invalid credentials. Check your password or identifier.');
          } else if (res.status >= 500) {
            setError('Server error. Please try again shortly.');
          } else {
            setError(data?.message || 'Unable to sign in.');
          }
        }
      }
    } catch (err) {
      setError('Cannot reach server. Is http://localhost:5000 running?');
      console.error('🚨 Critical login error:', err);
    } finally {
      setIsLoading(false);
    }
  };

  // Enter key support
  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && canSubmit) {
      submitRef.current?.click();
    }
  };

  return (
    <div className="min-h-screen flex">
      {/* ... Your existing JSX layout unchanged ... */}
      {/* Left: Enhanced form section */}
      {/* ... */}
      {/* Your entire component JSX goes here unchanged from your original code */}
    </div>
  );
};


// Util: defensively parse JSON
async function safeJson(res) {
  try {
    return await res.json();
  } catch {
    return {};
  }
}

// Validator hook
function useCallbackFormValidator() {
  const validate = (values) => {
    const errors = { identifier: '', password: '' };
    const id = String(values.identifier || '').trim();

    if (!id) {
      errors.identifier = 'Identifier is required';
    } else if (id.includes('@')) {
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(id)) {
        errors.identifier = 'Invalid email format';
      }
    } else {
      if (!/^[A-Za-z0-9._-]{4,}$/.test(id)) {
        errors.identifier = 'Use a valid plate, RFID, or email';
      }
    }

    if (!values.password || !String(values.password).trim()) {
      errors.password = 'Password is required';
    } else if (String(values.password).length < 4) {
      errors.password = 'Password is too short (min 4 characters)';
    }

    return errors;
  };

  return validate;
}

export default LoginPage;
