import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useAuth } from './contexts/AuthContext';
import { useAdminData } from './hooks/useAdminData';
import {
  LayoutDashboard, Users, Activity, Camera, FileText,
  Settings, LogOut, Bell, Menu, X, BarChart3, RefreshCw, WifiOff, Wifi, Wallet,
  ChevronsLeft, ChevronsRight
} from 'lucide-react';

// Admin components
import AdminOverview from './components/admin/AdminOverview';
import Analytics from './components/admin/Analytics';
import TollEvents from './components/admin/TollEvents';
import UserManagement from './components/admin/UserManagement';
import Snapshots from './components/admin/Snapshots';
import Reports from './components/admin/Reports';
import RechargeRequests from './components/admin/RechargeRequests';
import SystemSettings from './components/admin/SystemSettings';
import Notifications from './components/user/Notifications';

const VIEW_DEFAULT = 'overview';
const VIEWS = ['overview', 'analytics', 'events', 'users', 'snapshots', 'reports', 'recharge', 'settings', 'notifications'];

function getInitialView() {
  const hash = (typeof window !== 'undefined' ? window.location.hash : '') || '';
  const view = hash.replace('#', '');
  return VIEWS.includes(view) ? view : VIEW_DEFAULT;
}

const AdminApp = () => {
  const { user, logout } = useAuth();
  const [currentView, setCurrentView] = useState(() => getInitialView());
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [confirmLogout, setConfirmLogout] = useState(false);
  const mainRef = useRef(null);

  const {
    stats,
    events,
    users,
    rechargeRequests,
    notifications,
    isConnected,
    refreshData
  } = useAdminData();

  // Calculate unread notifications count
  const unreadCount = useMemo(() => {
    const notifArray = Array.isArray(notifications) ? notifications : [];
    return notifArray.filter(n => !n.read && !n.is_read).length;
  }, [notifications]);

  const menuItems = useMemo(() => ([
    { id: 'overview', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'analytics', label: 'Analytics', icon: BarChart3 },
    { id: 'events', label: 'Live Events', icon: Activity },
    { id: 'users', label: 'User Management', icon: Users },
    { id: 'snapshots', label: 'Snapshots', icon: Camera },
    { id: 'reports', label: 'Reports', icon: FileText },
    { id: 'recharge', label: 'Recharge Requests', icon: Wallet },
    { id: 'settings', label: 'System Settings', icon: Settings },
  ]), []);

  // Deep-link: sync hash -> view
  useEffect(() => {
    const onHashChange = () => {
      const next = window.location.hash.replace('#', '');
      if (VIEWS.includes(next)) setCurrentView(next);
    };
    window.addEventListener('hashchange', onHashChange);
    return () => window.removeEventListener('hashchange', onHashChange);
  }, []);

  // Deep-link: sync view -> hash
  useEffect(() => {
    const target = `#${currentView}`;
    if (window.location.hash !== target) window.location.hash = target;
  }, [currentView]);

  const jumpTo = useCallback((view) => {
    if (!VIEWS.includes(view)) view = VIEW_DEFAULT;
    setCurrentView(view);
    if (window.innerWidth < 1024) setIsSidebarOpen(false);
    setTimeout(() => mainRef.current?.focus(), 50);
  }, []);

  const onReconnect = async () => {
    if (typeof refreshData === 'function') {
      try {
        await refreshData();
      } catch {
        // optional toast
      }
    }
  };

  const props = useMemo(() => ({
    stats: stats || {},
    events: Array.isArray(events) ? events : [],
    users: Array.isArray(users) ? users : [],
    rechargeRequests: Array.isArray(rechargeRequests) ? rechargeRequests : [],
    notifications: Array.isArray(notifications) ? notifications : [],
    refreshData,
    isConnected: !!isConnected,
    userData: { ...user, role: 'admin', username: user?.name || 'admin' }
  }), [stats, events, users, rechargeRequests, notifications, refreshData, isConnected, user]);

  const renderView = () => {
    switch (currentView) {
      case 'overview': return <AdminOverview {...props} />;
      case 'analytics': return <Analytics {...props} />;
      case 'events': return <TollEvents {...props} />;
      case 'users': return <UserManagement {...props} />;
      case 'snapshots': return <Snapshots {...props} />;
      case 'reports': return <Reports {...props} />;
      case 'recharge': return <RechargeRequests {...props} />;
      case 'settings': return <SystemSettings {...props} />;
      case 'notifications': return <Notifications {...props} />;
      default: return <AdminOverview {...props} />;
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-white">
      {/* Top Nav */}
      <nav className="fixed top-0 left-0 right-0 z-20 border-b border-gray-200 bg-white/80 backdrop-blur supports-[backdrop-filter]:bg-white/60">
        <div className="px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            {/* Left */}
            <div className="flex items-center gap-4">
              {/* Mobile Hamburger */}
              <button
                onClick={() => setIsSidebarOpen(!isSidebarOpen)}
                className="p-2 rounded-lg hover:bg-gray-100 transition-colors lg:hidden"
                aria-label="Toggle sidebar"
                aria-expanded={isSidebarOpen}
              >
                {isSidebarOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
              </button>

              {/* Desktop Toggle Button */}
              <button
                onClick={() => setIsSidebarOpen(!isSidebarOpen)}
                className="hidden lg:flex p-2 rounded-lg hover:bg-indigo-50 transition-all duration-200 items-center gap-2 group border border-transparent hover:border-indigo-200"
                aria-label="Toggle sidebar"
                title={isSidebarOpen ? 'Collapse sidebar' : 'Expand sidebar'}
              >
                {isSidebarOpen ? (
                  <ChevronsLeft className="w-5 h-5 text-gray-600 group-hover:text-indigo-600 transition-colors" />
                ) : (
                  <ChevronsRight className="w-5 h-5 text-gray-600 group-hover:text-indigo-600 transition-colors" />
                )}
              </button>

              <a
                href="#overview"
                onClick={(e) => { e.preventDefault(); jumpTo('overview'); }}
                className="group flex items-center gap-3 focus:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500 rounded-lg"
              >
                <span className="w-10 h-10 bg-gradient-to-br from-indigo-600 to-purple-600 rounded-lg flex items-center justify-center shadow-md group-hover:shadow-lg transition-shadow">
                  <Activity className="w-6 h-6 text-white" />
                </span>
                <span>
                  <h1 className="text-xl font-bold text-gray-900 tracking-tight leading-5">Smart Toll</h1>
                  <p className="text-xs text-gray-500 -mt-0.5">Admin Dashboard</p>
                </span>
              </a>
            </div>

            {/* Center status + actions */}
            <div className="hidden md:flex items-center gap-2 px-2 py-1.5 bg-gray-50 rounded-full border border-gray-200">
              <span className={`inline-block w-2 h-2 rounded-full animate-pulse ${isConnected ? 'bg-green-500' : 'bg-red-500'}`} />
              <span className="text-sm font-medium text-gray-700">
                {isConnected ? 'Live' : 'Offline'}
              </span>
              <button
                onClick={refreshData}
                className="ml-1 p-1.5 rounded hover:bg-gray-100 focus-visible:ring-2 focus-visible:ring-indigo-500 transition-colors"
                aria-label="Refresh data"
                title="Refresh"
              >
                <RefreshCw className="w-4 h-4 text-gray-700" />
              </button>
              {!isConnected ? (
                <button
                  onClick={onReconnect}
                  className="ml-0.5 p-1.5 rounded hover:bg-gray-100 focus-visible:ring-2 focus-visible:ring-indigo-500 transition-colors"
                  aria-label="Reconnect"
                  title="Reconnect"
                >
                  <WifiOff className="w-4 h-4 text-gray-700" />
                </button>
              ) : (
                <Wifi className="w-4 h-4 ml-0.5 text-gray-500" />
              )}
            </div>

            {/* Right */}
            <div className="flex items-center gap-3">
              <button
                onClick={() => jumpTo('notifications')}
                className="relative p-2 rounded-lg hover:bg-gray-100 transition-colors focus-visible:ring-2 focus-visible:ring-indigo-500"
                aria-label="Notifications"
                title="Notifications"
              >
                <Bell className="w-6 h-6 text-gray-600" />
                {unreadCount > 0 && (
                  <span className="absolute top-1 right-1 min-w-[20px] h-5 px-1 bg-red-500 text-white text-xs rounded-full flex items-center justify-center font-bold shadow-md animate-pulse">
                    {unreadCount}
                  </span>
                )}
              </button>

              <div className="flex items-center gap-3 pl-3 border-l border-gray-200">
                <div className="hidden sm:block text-right">
                  <p className="text-sm font-medium text-gray-900">{user?.name || 'Admin'}</p>
                  <p className="text-xs text-gray-500">Administrator</p>
                </div>
                <div
                  className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-500 rounded-full flex items-center justify-center text-white font-bold shadow-md select-none"
                  aria-label={`Account avatar for ${user?.name || 'Admin'}`}
                >
                  {(user?.name?.charAt(0) || 'A').toUpperCase()}
                </div>
              </div>

              <button
                onClick={() => setConfirmLogout(true)}
                className="flex items-center gap-2 px-3 py-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors font-medium focus-visible:ring-2 focus-visible:ring-red-500"
                title="Logout"
              >
                <LogOut className="w-5 h-5" />
                <span className="hidden sm:inline">Logout</span>
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Sidebar */}
      <aside
        className={`fixed top-16 left-0 bottom-0 w-68 max-w-[272px] bg-white/90 backdrop-blur border-r border-gray-200 transition-all duration-300 ease-in-out z-10 shadow-lg ${
          isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:-translate-x-full'
        } lg:translate-x-0`}
        aria-label="Sidebar"
      >
        <div className="p-4 space-y-1.5 overflow-y-auto h-full">
          {menuItems.map((item) => {
            const Icon = item.icon;
            const isActive = currentView === item.id;
            return (
              <button
                key={item.id}
                onClick={() => jumpTo(item.id)}
                className={`w-full flex items-center gap-3 px-4 py-3.5 rounded-xl transition-all duration-200 text-left group ${
                  isActive
                    ? 'bg-gradient-to-r from-indigo-600 to-purple-600 text-white font-semibold shadow-lg scale-[1.02]'
                    : 'text-gray-700 hover:bg-gray-100 hover:scale-[1.01]'
                } focus-visible:ring-2 focus-visible:ring-indigo-500`}
                aria-current={isActive ? 'page' : undefined}
              >
                <span className={`p-2.5 rounded-lg transition-all ${isActive ? 'bg-white/20' : 'bg-gray-100 group-hover:bg-white group-hover:shadow-md'}`}>
                  <Icon className={`w-5 h-5 ${isActive ? 'text-white' : 'text-gray-700'}`} />
                </span>
                <span className="flex-1 min-w-0 truncate text-base">
                  {item.label}
                </span>
              </button>
            );
          })}
        </div>
      </aside>

      {/* Main Content */}
      <main
        ref={mainRef}
        tabIndex={-1}
        className={`pt-16 outline-none transition-all duration-300 ease-in-out ${isSidebarOpen ? 'lg:pl-[272px]' : 'lg:pl-0'}`}
        aria-live="polite"
      >
        <div className="p-4 sm:p-6 lg:p-8">
          {!isConnected && (
            <div className="mb-4 p-4 rounded-xl border-2 border-amber-200 bg-gradient-to-r from-amber-50 to-orange-50 text-amber-900 text-sm flex items-center justify-between shadow-sm">
              <div className="flex items-center gap-3">
                <WifiOff className="w-5 h-5 flex-shrink-0" />
                <span className="font-medium">Connection offline. Data may not be current.</span>
              </div>
              <div className="flex items-center gap-2">
                <button
                  onClick={refreshData}
                  className="px-3 py-1.5 rounded-lg bg-white hover:bg-amber-100 border border-amber-200 transition-colors font-medium text-sm"
                >
                  Refresh
                </button>
                <button
                  onClick={onReconnect}
                  className="px-3 py-1.5 rounded-lg bg-white hover:bg-amber-100 border border-amber-200 transition-colors font-medium text-sm"
                >
                  Reconnect
                </button>
              </div>
            </div>
          )}
          {renderView()}
        </div>
      </main>

      {/* Overlay for mobile */}
      {isSidebarOpen && (
        <div
          className="fixed inset-0 bg-black/40 z-10 lg:hidden backdrop-blur-sm transition-opacity duration-300"
          onClick={() => setIsSidebarOpen(false)}
          aria-hidden="true"
        />
      )}

      {/* Mobile floating actions */}
      <div className="fixed bottom-4 right-4 lg:hidden flex gap-2 z-20">
        <button
          onClick={refreshData}
          className="p-3 rounded-full shadow-lg bg-white border border-gray-200 hover:bg-gray-50 focus-visible:ring-2 focus-visible:ring-indigo-500 transition-all"
          aria-label="Refresh data"
          title="Refresh"
        >
          <RefreshCw className="w-5 h-5 text-gray-700" />
        </button>
        <button
          onClick={onReconnect}
          className="p-3 rounded-full shadow-lg bg-white border border-gray-200 hover:bg-gray-50 focus-visible:ring-2 focus-visible:ring-indigo-500 transition-all"
          aria-label="Reconnect"
          title="Reconnect"
        >
          {isConnected ? <Wifi className="w-5 h-5 text-green-600" /> : <WifiOff className="w-5 h-5 text-red-600" />}
        </button>
      </div>

      {/* Logout confirmation modal */}
      {confirmLogout && (
        <div className="fixed inset-0 z-30 flex items-center justify-center bg-black/50 p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm p-6 animate-scale-in">
            <div className="flex items-center gap-3 mb-4">
              <div className="p-3 bg-red-100 rounded-full">
                <LogOut className="w-6 h-6 text-red-600" />
              </div>
              <h3 className="text-xl font-bold text-gray-900">Confirm Logout</h3>
            </div>
            <p className="text-sm text-gray-600 mb-6">Are you sure you want to log out of the admin dashboard?</p>
            <div className="flex items-center justify-end gap-3">
              <button
                onClick={() => setConfirmLogout(false)}
                className="px-5 py-2.5 rounded-lg border-2 border-gray-300 hover:bg-gray-50 text-sm font-semibold focus-visible:ring-2 focus-visible:ring-gray-300 transition-all"
              >
                Cancel
              </button>
              <button
                onClick={logout}
                className="px-5 py-2.5 rounded-lg bg-red-600 text-white hover:bg-red-700 text-sm font-semibold focus-visible:ring-2 focus-visible:ring-red-500 shadow-md transition-all flex items-center gap-2"
              >
                <LogOut className="w-4 h-4" />
                Logout
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminApp;
