import React from 'react';
import { AuthProvider, useAuth } from './contexts/AuthContext';
import LoginPage from './components/LoginPage';
import AdminApp from './AdminApp';
import UserApp from './UserApp';
import { Activity, Loader2, Zap } from 'lucide-react';

/**
 * Enhanced Splash Screen with professional design
 * - Smooth animations
 * - Modern gradient background
 * - Better loading indicators
 * - Accessibility features
 */
const Splash = () => {
  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-indigo-50 via-purple-50 to-pink-50 relative overflow-hidden">
      {/* Animated background elements */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-1/4 left-1/4 w-64 h-64 bg-indigo-200/30 rounded-full blur-3xl animate-pulse" />
        <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-purple-200/30 rounded-full blur-3xl animate-pulse delay-700" />
        <div className="absolute top-1/2 left-1/2 w-80 h-80 bg-pink-200/20 rounded-full blur-3xl animate-pulse delay-1000" />
      </div>

      <div className="relative text-center z-10">
        {/* Logo container with pulsing effect */}
        <div
          className="inline-flex items-center justify-center w-24 h-24 rounded-2xl bg-white shadow-2xl ring-4 ring-indigo-100 mb-6 relative"
          aria-hidden="true"
        >
          {/* Outer pulse ring */}
          <div className="absolute inset-0 rounded-2xl bg-indigo-500/20 animate-ping" />

          {/* Inner animated icon */}
          <div className="relative">
            <div className="absolute inset-0 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-full blur-md opacity-50 animate-pulse" />
            <Activity className="relative w-12 h-12 text-indigo-600 animate-bounce" />
          </div>
        </div>

        {/* Spinner with gradient */}
        <div className="relative inline-flex mb-6">
          <div
            className="animate-spin rounded-full h-16 w-16 border-4 border-transparent bg-gradient-to-r from-indigo-600 via-purple-600 to-pink-600 p-1"
            style={{
              backgroundClip: 'padding-box',
              WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
              WebkitMaskComposite: 'xor',
              maskComposite: 'exclude'
            }}
            role="status"
            aria-label="Loading application"
          >
            <div className="h-full w-full rounded-full bg-gradient-to-br from-indigo-50 to-purple-50" />
          </div>
          <Loader2 className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-6 h-6 text-indigo-600 animate-spin" />
        </div>

        {/* Text content */}
        <div className="space-y-2 animate-fade-in">
          <h2 className="text-2xl font-bold text-gray-900 flex items-center justify-center gap-2">
            <Zap className="w-6 h-6 text-indigo-600" />
            Smart Toll System
          </h2>
          <p className="text-lg font-semibold text-gray-700">Initializing Dashboard</p>
          <p className="text-sm text-gray-500">Please wait while we prepare your experience</p>
        </div>

        {/* Loading dots animation */}
        <div className="flex items-center justify-center gap-2 mt-6">
          <div className="w-2 h-2 bg-indigo-600 rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
          <div className="w-2 h-2 bg-purple-600 rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
          <div className="w-2 h-2 bg-pink-600 rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
        </div>
      </div>
    </div>
  );
};

/**
 * Smart role-based router
 * - Routes users to correct dashboard based on role
 * - Fallback to user dashboard for safety
 */
const RoleRouter = ({ userType, user }) => {
  if (userType === 'admin') {
    return <AdminApp user={user} />;
  }

  if (userType === 'user') {
    return <UserApp user={user} />;
  }

  // Fallback: default to user experience
  console.warn(`Unknown user type: ${userType}. Defaulting to user dashboard.`);
  return <UserApp user={user} />;
};

/**
 * Main app content with authentication routing
 * - Shows splash during initial load
 * - Routes to login or dashboard based on auth state
 * - Smooth transitions between states
 */
const AppContent = () => {
  const { isAuthenticated, userType, user, loading } = useAuth();

  // Show splash screen during authentication check
  if (loading) {
    return <Splash />;
  }

  // Show login page if not authenticated
  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-50 via-white to-gray-50">
        <div className="motion-safe:animate-fade-in">
          <LoginPage />
        </div>
      </div>
    );
  }

  // Show appropriate dashboard based on user role
  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-white transition-colors duration-500">
      <div className="motion-safe:animate-fade-in">
        <RoleRouter userType={userType} user={user} />
      </div>
    </div>
  );
};

/**
 * Root App component
 * - Provides authentication context
 * - Sets up global focus styles
 * - Ensures accessibility features
 */
const App = () => {
  return (
    <AuthProvider>
      <div className="antialiased">
        {/* Global focus ring for accessibility */}
        <style jsx global>{`
          * {
            @apply focus:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500 focus-visible:ring-offset-2;
          }

          /* Smooth fade-in animation */
          @keyframes fade-in {
            from {
              opacity: 0;
              transform: translateY(10px);
            }
            to {
              opacity: 1;
              transform: translateY(0);
            }
          }

          .animate-fade-in {
            animation: fade-in 0.5s ease-out;
          }

          /* Reduced motion support */
          @media (prefers-reduced-motion: reduce) {
            * {
              animation-duration: 0.01ms !important;
              animation-iteration-count: 1 !important;
              transition-duration: 0.01ms !important;
            }
          }
        `}</style>

        <AppContent />
      </div>
    </AuthProvider>
  );
};

export default App;
