import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useAuth } from './contexts/AuthContext';
import { useUserData } from './hooks/useUserData';
import {
  LayoutDashboard, Receipt, Bell, Settings,
  LogOut, Menu, X, Activity, Wallet, RefreshCw, WifiOff, Wifi,
  ChevronsLeft, ChevronsRight, TrendingUp
} from 'lucide-react';

// User components
import UserDashboard from './components/user/UserDashboard';
import TransactionHistory from './components/user/TransactionHistory';
import BalanceManager from './components/user/BalanceManager';
import Notifications from './components/user/Notifications';
import ProfileSettings from './components/user/ProfileSettings';

const VIEW_DEFAULT = 'dashboard';
const VIEWS = ['dashboard', 'transactions', 'balance', 'notifications', 'settings'];

function getInitialView() {
  const hash = (typeof window !== 'undefined' ? window.location.hash : '') || '';
  const view = hash.replace('#', '');
  return VIEWS.includes(view) ? view : VIEW_DEFAULT;
}

const UserApp = () => {
  const { user, logout } = useAuth();
  const [currentView, setCurrentView] = useState(() => getInitialView());
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [confirmLogout, setConfirmLogout] = useState(false);
  const mainRef = useRef(null);

  const {
    balance,
    transactions,
    notifications: userNotifications,
    profile,
    stats,
    isConnected,
    loading,
    refreshData
  } = useUserData();

  // Derive counts safely
  const unread = useMemo(
    () => (Array.isArray(userNotifications) ? userNotifications.filter(n => !n?.is_read && !n?.read).length : 0),
    [userNotifications]
  );
  const userDisplayName = user?.name || profile?.owner_name || 'User';
  const userEmail = user?.email || profile?.email || '';

  // Menu items
  const menuItems = useMemo(() => ([
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'transactions', label: 'Transaction History', icon: Receipt },
    { id: 'balance', label: 'Balance Manager', icon: Wallet },
    { id: 'notifications', label: 'Notifications', icon: Bell, badge: unread },
    { id: 'settings', label: 'Profile Settings', icon: Settings },
  ]), [unread]);

  // Deep-link view via hash
  useEffect(() => {
    const onHashChange = () => {
      const next = window.location.hash.replace('#', '');
      if (VIEWS.includes(next)) {
        setCurrentView(next);
      }
    };
    window.addEventListener('hashchange', onHashChange);
    return () => window.removeEventListener('hashchange', onHashChange);
  }, []);

  // Keep hash in sync when programmatically switching views
  useEffect(() => {
    if (!currentView) return;
    const targetHash = `#${currentView}`;
    if (window.location.hash !== targetHash) {
      window.location.hash = targetHash;
    }
  }, [currentView]);

  const jumpTo = useCallback((view) => {
    if (!VIEWS.includes(view)) view = VIEW_DEFAULT;
    setCurrentView(view);
    if (window.innerWidth < 1024) setIsSidebarOpen(false);
    setTimeout(() => mainRef.current?.focus(), 50);
  }, []);

  const onReconnect = async () => {
    if (typeof refreshData === 'function') {
      try {
        await refreshData();
      } catch {
        // Optional: toast
      }
    }
  };

  // Shared props passed down to user components
  const props = useMemo(() => ({
    balance: typeof balance === 'number' ? balance : 0,
    transactions: Array.isArray(transactions) ? transactions : [],
    notifications: Array.isArray(userNotifications) ? userNotifications : [],
    profile: profile || {},
    stats: stats || {},
    userData: profile || {},
    isConnected: !!isConnected,
    refreshData
  }), [balance, transactions, userNotifications, profile, stats, isConnected, refreshData]);

  const renderView = () => {
    switch (currentView) {
      case 'dashboard': return <UserDashboard {...props} />;
      case 'transactions': return <TransactionHistory {...props} />;
      case 'balance': return <BalanceManager {...props} />;
      case 'notifications': return <Notifications {...props} />;
      case 'settings': return <ProfileSettings {...props} />;
      default: return <UserDashboard {...props} />;
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-green-50 via-teal-50 to-emerald-50">
        <div className="text-center">
          <div className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-white shadow-lg mb-4">
            <Activity className="w-10 h-10 text-green-600 animate-pulse" />
          </div>
          <div className="animate-spin rounded-full h-12 w-12 border-4 border-green-600 border-t-transparent mx-auto mb-4"></div>
          <p className="text-gray-700 font-semibold text-lg">Loading your dashboard</p>
          <p className="text-gray-500 text-sm mt-1">Please wait...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-white">
      {/* Top Nav */}
      <nav className="fixed top-0 left-0 right-0 z-20 border-b border-gray-200 bg-white/80 backdrop-blur supports-[backdrop-filter]:bg-white/60">
        <div className="px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            {/* Left */}
            <div className="flex items-center gap-4">
              {/* Mobile Hamburger */}
              <button
                onClick={() => setIsSidebarOpen(!isSidebarOpen)}
                className="p-2 rounded-lg hover:bg-gray-100 transition-colors lg:hidden"
                aria-label="Toggle sidebar"
                aria-expanded={isSidebarOpen}
              >
                {isSidebarOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
              </button>

              {/* Desktop Toggle Button */}
              <button
                onClick={() => setIsSidebarOpen(!isSidebarOpen)}
                className="hidden lg:flex p-2 rounded-lg hover:bg-green-50 transition-all duration-200 items-center gap-2 group border border-transparent hover:border-green-200"
                aria-label="Toggle sidebar"
                title={isSidebarOpen ? 'Collapse sidebar' : 'Expand sidebar'}
              >
                {isSidebarOpen ? (
                  <ChevronsLeft className="w-5 h-5 text-gray-600 group-hover:text-green-600 transition-colors" />
                ) : (
                  <ChevronsRight className="w-5 h-5 text-gray-600 group-hover:text-green-600 transition-colors" />
                )}
              </button>

              <a
                href="#dashboard"
                onClick={(e) => { e.preventDefault(); jumpTo('dashboard'); }}
                className="group flex items-center gap-3 focus:outline-none focus-visible:ring-2 focus-visible:ring-green-500 rounded-lg"
              >
                <span className="w-10 h-10 bg-gradient-to-br from-green-600 to-teal-600 rounded-lg flex items-center justify-center shadow-md group-hover:shadow-lg transition-shadow">
                  <Activity className="w-6 h-6 text-white" />
                </span>
                <span>
                  <h1 className="text-xl font-bold text-gray-900 tracking-tight leading-5">Smart Toll</h1>
                  <p className="text-xs text-gray-500 -mt-0.5">User Dashboard</p>
                </span>
              </a>
            </div>

            {/* Center balance pill */}
            <div className="hidden md:flex items-center gap-2 px-3 py-1.5 rounded-full border border-green-200 bg-gradient-to-r from-green-50 to-teal-50">
              <Wallet className="w-5 h-5 text-green-700" />
              <span className="text-sm font-semibold text-green-800 tabular-nums">
                {typeof balance === 'number' ? `${balance.toFixed(2)} DA` : '0.00 DA'}
              </span>
              <button
                onClick={refreshData}
                className="ml-2 p-1.5 rounded hover:bg-green-100 transition-colors focus-visible:ring-2 focus-visible:ring-green-500"
                aria-label="Refresh data"
                title="Refresh"
              >
                <RefreshCw className="w-4 h-4 text-green-700" />
              </button>
            </div>

            {/* Right */}
            <div className="flex items-center gap-3">
              {/* Connection status */}
              <div className={`hidden md:flex items-center gap-2 px-2 py-1.5 rounded-full text-xs font-medium ${
                isConnected ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'
              }`}>
                <span className={`inline-block w-2 h-2 rounded-full animate-pulse ${isConnected ? 'bg-green-500' : 'bg-red-500'}`} />
                <span>{isConnected ? 'Live' : 'Offline'}</span>
                {!isConnected ? (
                  <button onClick={onReconnect} className="ml-1 p-1 rounded hover:bg-red-100 transition-colors" aria-label="Reconnect">
                    <WifiOff className="w-3 h-3" />
                  </button>
                ) : (
                  <Wifi className="w-3 h-3 ml-1 opacity-70" />
                )}
              </div>

              {/* Notifications */}
              <button
                onClick={() => jumpTo('notifications')}
                className="relative p-2 rounded-lg hover:bg-gray-100 transition-colors focus-visible:ring-2 focus-visible:ring-green-500"
                aria-label="Open notifications"
                title="Notifications"
              >
                <Bell className="w-6 h-6 text-gray-600" />
                {unread > 0 && (
                  <span className="absolute top-1 right-1 min-w-[18px] h-5 px-1 bg-red-500 text-white text-xs rounded-full flex items-center justify-center font-bold">
                    {unread}
                  </span>
                )}
              </button>

              {/* User profile */}
              <div className="flex items-center gap-3 pl-3 border-l border-gray-200">
                <div className="hidden sm:block text-right leading-tight">
                  <p className="text-sm font-medium text-gray-900">{userDisplayName}</p>
                  <p className="text-xs text-gray-500 truncate max-w-[180px]">{userEmail || '—'}</p>
                </div>
                <div
                  className="w-10 h-10 bg-gradient-to-br from-green-500 to-teal-500 rounded-full flex items-center justify-center text-white font-bold shadow-md select-none"
                  aria-label={`Account avatar for ${userDisplayName}`}
                >
                  {(userDisplayName?.charAt(0) || 'U').toUpperCase()}
                </div>
              </div>

              {/* Logout */}
              <button
                onClick={() => setConfirmLogout(true)}
                className="flex items-center gap-2 px-3 py-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors font-medium focus-visible:ring-2 focus-visible:ring-red-500"
                title="Logout"
              >
                <LogOut className="w-5 h-5" />
                <span className="hidden sm:inline">Logout</span>
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Clean Sidebar */}
      <aside
        className={`fixed top-16 left-0 bottom-0 w-64 bg-white/90 backdrop-blur border-r border-gray-200 transition-all duration-300 ease-in-out z-10 shadow-lg ${
          isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:-translate-x-full'
        } lg:translate-x-0`}
        aria-label="Sidebar"
      >
        <div className="p-4 space-y-3 overflow-y-auto h-full">
          {/* Balance card - Enhanced */}
          <div className="p-4 bg-gradient-to-br from-green-500 to-teal-600 rounded-xl shadow-lg text-white">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                <Wallet className="w-5 h-5" />
                <p className="text-sm font-medium opacity-90">Current Balance</p>
              </div>
              {typeof balance === 'number' && balance < 100 && (
                <span className="text-xs bg-orange-500 px-2 py-0.5 rounded-full font-bold">Low</span>
              )}
            </div>
            <p className="text-3xl font-bold mb-1 tabular-nums">
              {typeof balance === 'number' ? `${balance.toFixed(2)} DA` : '0.00 DA'}
            </p>
            <div className="flex items-center gap-1 text-xs opacity-75 mb-3">
              <TrendingUp className="w-3 h-3" />
              <span>Updated just now</span>
            </div>
            <button
              onClick={() => jumpTo('balance')}
              className="w-full py-2.5 bg-white text-green-700 text-sm font-semibold rounded-lg hover:bg-green-50 transition-all shadow-md hover:shadow-lg"
            >
              Recharge Now
            </button>
          </div>

          {/* Menu items - Enhanced */}
          <nav className="space-y-1.5">
            {menuItems.map((item) => {
              const Icon = item.icon;
              const isActive = currentView === item.id;
              return (
                <button
                  key={item.id}
                  onClick={() => jumpTo(item.id)}
                  className={`w-full flex items-center justify-between px-4 py-3.5 rounded-xl transition-all duration-200 group ${
                    isActive
                      ? 'bg-gradient-to-r from-green-500 to-teal-500 text-white font-semibold shadow-lg scale-[1.02]'
                      : 'text-gray-700 hover:bg-gray-100 hover:scale-[1.01]'
                  } focus-visible:ring-2 focus-visible:ring-green-500`}
                  aria-current={isActive ? 'page' : undefined}
                >
                  <div className="flex items-center gap-3">
                    <span className={`p-2 rounded-lg transition-all ${isActive ? 'bg-white/20' : 'bg-gray-100 group-hover:bg-white group-hover:shadow-md'}`}>
                      <Icon className="w-5 h-5" />
                    </span>
                    <span className="text-base">{item.label}</span>
                  </div>
                  {(item.badge || 0) > 0 && (
                    <span className="px-2 py-0.5 bg-red-500 text-white text-xs font-bold rounded-full min-w-[20px] text-center shadow-md">
                      {item.badge}
                    </span>
                  )}
                </button>
              );
            })}
          </nav>
        </div>
      </aside>

      {/* Main Content */}
      <main
        ref={mainRef}
        tabIndex={-1}
        className={`pt-16 outline-none transition-all duration-300 ease-in-out ${isSidebarOpen ? 'lg:pl-64' : 'lg:pl-0'}`}
        aria-live="polite"
      >
        <div className="p-4 sm:p-6 lg:p-8">
          {/* Offline banner */}
          {!isConnected && (
            <div className="mb-4 p-4 rounded-xl border-2 border-amber-200 bg-gradient-to-r from-amber-50 to-orange-50 text-amber-900 text-sm flex items-center justify-between shadow-sm">
              <div className="flex items-center gap-3">
                <WifiOff className="w-5 h-5 flex-shrink-0" />
                <span className="font-medium">Connection offline. Data may not be current.</span>
              </div>
              <div className="flex items-center gap-2">
                <button
                  onClick={refreshData}
                  className="px-3 py-1.5 rounded-lg bg-white hover:bg-amber-100 border border-amber-200 transition-colors font-medium"
                >
                  Refresh
                </button>
                <button
                  onClick={onReconnect}
                  className="px-3 py-1.5 rounded-lg bg-white hover:bg-amber-100 border border-amber-200 transition-colors font-medium"
                >
                  Reconnect
                </button>
              </div>
            </div>
          )}
          {renderView()}
        </div>
      </main>

      {/* Overlay for mobile */}
      {isSidebarOpen && (
        <div
          className="fixed inset-0 bg-black/40 z-10 lg:hidden backdrop-blur-sm transition-opacity duration-300"
          onClick={() => setIsSidebarOpen(false)}
          aria-hidden="true"
        />
      )}

      {/* Mobile floating actions */}
      <div className="fixed bottom-4 right-4 lg:hidden flex gap-2 z-20">
        <button
          onClick={refreshData}
          className="p-3 rounded-full shadow-lg bg-white border border-gray-200 hover:bg-gray-50 focus-visible:ring-2 focus-visible:ring-green-500 transition-all"
          aria-label="Refresh data"
          title="Refresh"
        >
          <RefreshCw className="w-5 h-5 text-gray-700" />
        </button>
        <button
          onClick={onReconnect}
          className="p-3 rounded-full shadow-lg bg-white border border-gray-200 hover:bg-gray-50 focus-visible:ring-2 focus-visible:ring-green-500 transition-all"
          aria-label="Reconnect"
          title="Reconnect"
        >
          {isConnected ? <Wifi className="w-5 h-5 text-green-600" /> : <WifiOff className="w-5 h-5 text-red-600" />}
        </button>
      </div>

      {/* Logout confirmation modal - Enhanced */}
      {confirmLogout && (
        <div className="fixed inset-0 z-30 flex items-center justify-center bg-black/50 p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm p-6 animate-scale-in">
            <div className="flex items-center gap-3 mb-4">
              <div className="p-3 bg-red-100 rounded-full">
                <LogOut className="w-6 h-6 text-red-600" />
              </div>
              <h3 className="text-xl font-bold text-gray-900">Confirm Logout</h3>
            </div>
            <p className="text-sm text-gray-600 mb-6">Are you sure you want to log out of your account?</p>
            <div className="flex items-center justify-end gap-3">
              <button
                onClick={() => setConfirmLogout(false)}
                className="px-5 py-2.5 rounded-lg border-2 border-gray-300 hover:bg-gray-50 text-sm font-semibold focus-visible:ring-2 focus-visible:ring-gray-300 transition-all"
              >
                Cancel
              </button>
              <button
                onClick={logout}
                className="px-5 py-2.5 rounded-lg bg-red-600 text-white hover:bg-red-700 text-sm font-semibold focus-visible:ring-2 focus-visible:ring-red-500 shadow-md transition-all flex items-center gap-2"
              >
                <LogOut className="w-4 h-4" />
                Logout
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default UserApp;
